newrels=[r for r in rels if r['child'] in extension_tables or (r['child']=='outbox_event' and r['column'] in ['account_id','integration_contract_id'])]
for r in newrels:sql.append(f'ALTER TABLE {q(r["child"])} ADD CONSTRAINT {q("fk_v3_"+r["id"].lower().replace("-","_"))} FOREIGN KEY ({q(r["column"])}) REFERENCES {q(r["parent"])} ({q(r.get("parent_column","id"))}) ON UPDATE RESTRICT ON DELETE RESTRICT;')
for i,(t,cols,p,pcols) in enumerate(composite):sql.append(f'ALTER TABLE {q(t)} ADD CONSTRAINT fk_v3_account_scope_{i+1} FOREIGN KEY ({", ".join(map(q,cols))}) REFERENCES {q(p)} ({", ".join(map(q,pcols))}) ON UPDATE RESTRICT ON DELETE RESTRICT;')
for ix,t,cols,*_ in indexes[len(physical['indexes']):]:sql.append(f'CREATE INDEX {q(ix)} ON {q(t)} ({cols});')
sql+=['REVOKE ALL ON '+', '.join(map(q,extension_tables))+' FROM PUBLIC;','-- No direct runtime grants. A reviewed API/worker must enforce account ownership and vocabulary domains.','-- Dedicated runtime-role/RLS and provider-signature tests remain explicit release gates.','COMMIT;']
(OUT/'database/005_scale_integration.sql').write_text('\n\n'.join(sql),encoding='utf-8')
