# Source contracts. They are proposed Talentra-owned interfaces, not invented
# claims about a named provider's live API.
contracts=[]; mappings=[]; mapping_rows=[]; contract_rows=[]
def field(name,target,meaning,typ='string',required=True,transform='Validate type and length; reject invalid values',owner='Platform integration owner',conflict='Source owns this field; reject stale versions'):
 return dict(name=name,target=target,meaning=meaning,type=typ,required=required,transform=transform,owner=owner,conflict=conflict)
def contract(key,boundary,direction,fields,owner,priority='P0'):
 props={};required=[];cid=f'CON-{len(contracts)+1:03}'
 envelope=[field('event_id','integration_inbox.event_key' if direction=='Inbound' else 'outbox_event.event_key','Globally unique producer event key within contract'),field('correlation_id','integration_inbox.correlation_key' if direction=='Inbound' else 'TRANSPORT_ONLY','Safe trace correlation key'),field('schema_version','integration_contract.schema_version','Positive exact supported contract version','integer'),field('occurred_at','integration_inbox.occurred_at' if direction=='Inbound' else 'TRANSPORT_ONLY','UTC ISO8601 source timestamp'),field('source_version','integration_inbox.source_version' if direction=='Inbound' else 'TRANSPORT_ONLY','Monotonic aggregate version','integer')]
 fs=envelope+fields
 for f in fs:
  spec=dict(type=f['type'],description=f['meaning'])
  if f['type']=='string':spec['maxLength']=255 if f['name'] not in ['description','headline'] else 20000
  if f['type']=='integer':spec['minimum']=0
  if f['name'] in ['occurred_at','verified_at','reconciled_at']:spec['format']='date-time'
  if f['name'] in ['amount','estimated_amount','total_amount','projected_amount']:spec['pattern']=r'^\d{1,16}\.\d{2}$';spec['maxLength']=19
  if f['name']=='currency_code':spec.update(minLength=3,maxLength=3,pattern='^[A-Z]{3}$')
  if not f['required']:spec['type']=[f['type'],'null']
  props[f['name']]=spec
  if f['required']:required.append(f['name'])
 schema={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:talentra:'+key,'title':key,'type':'object','additionalProperties':False,'required':required,'properties':props}
 filename=key+'.schema.json';save(OUT/'contracts'/filename,schema)
 digest=hashlib.sha256((OUT/'contracts'/filename).read_bytes()).hexdigest()
 record=dict(id=cid,key=key,boundary=boundary,direction=direction,owner=owner,priority=priority,fields=fs,schema=schema,sha256=digest)
 contracts.append(record)
 contract_rows.append([cid,key,boundary,direction,owner,'Proposed v1; provider and business owner sign-off pending','JSON over HTTPS with provider-specific signature adapter','262144 bytes; proposed cap',len(fs),'contracts/'+filename,digest,priority])
