  nodes.append([s['number'],sid,'',1,section['name'],pri,'Major output section',src])
  for j,col in enumerate(section['columns']):
   values=[r[j] for r in section['rows'] if j<len(r) and r[j] is not None]
   typ='boolean' if values and all(isinstance(v,bool) for v in values) else 'integer' if values and all(type(v)==int for v in values) else 'decimal' if values and all(type(v) in [int,float] for v in values) else 'text'
   allowed='One scalar text value; no unexplained blanks; pending evidence must be labelled' if typ=='text' else 'TRUE or FALSE' if typ=='boolean' else 'Typed finite numeric value; unit and range stated in owning row'
   if col in ['Priority','Section priority']:allowed='P0 mandatory/release critical; P1 core supporting; P2 optional'
   if col in ['Class','Classification']:allowed='Public; Internal; Personal; Sensitive'
   if col=='Direction':allowed='Inbound; Outbound'
   if col=='Result':allowed='PASS; FAIL; NOT RUN; PENDING; layer must be explicit'
   definition=meaning(col,section['name']);reason='Needed to '+('prevent ambiguous field conversion and data loss at the source boundary' if s['number']==22 else 'evaluate the step exit condition: '+s['exit'])
