  required_cells=len(section['rows'])*len(section['columns']);filled=sum(v is not None and v!='' for r in section['rows'] for v in r)
  field_metrics.append(dict(step=s['number'],section=section['name'],priority=pri,fields=len(section['columns']),rows=len(section['rows']),conformance=all(len(r)==len(section['columns']) for r in section['rows']),fill=filled/required_cells if required_cells else 1,source=src))
